INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0c82d6b5-a04b-40b8-ad40-e686a22c19ea', '322a1e1c-b550-4cdb-b3f2-b7d59f9f503a', 'Disk Usage with df and awk', 'Run df -h to list filesystem usage. Pipe the output to awk to extract the Use% column (field 5) for the root filesystem /. Strip the percent sign and report the numeric value. What is the root disk usage percentage?', 100, '$2b$10$8iP2bGaoABrHuNk8zIPT6O6mGjWsmtBW9zrM9FIAIhnfrGlrhEutO');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9da10ee4-3a2e-4a2f-8dd0-570792554b04', '322a1e1c-b550-4cdb-b3f2-b7d59f9f503a', 'Crontab Scheduling', 'Run crontab -l to list current cron jobs. If no crontab exists, create one with crontab -e that runs echo hello >> /tmp/cron-test every 5 minutes. After saving, run crontab -l again to verify. What is the full cron entry line?', 100, '$2b$10$OR7dHUqr.rt8RFX61SC5t.fm4zAVXGNZiLl6p6ML8.uQJwDzLPVk6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('75748028-2554-4226-9f48-8c9fe7012773', '322a1e1c-b550-4cdb-b3f2-b7d59f9f503a', 'Symbolic and Hard Links', 'Create a file called link-source.txt containing the text hello. Then create a symbolic link called link-symlink.txt pointing to it. Also create a hard link called link-hardlink.txt pointing to it. Run ls -li on all three files. What inode number do link-source.txt and link-hardlink.txt share?', 100, '$2b$10$kMlVgEXonLrY0FMrQz6rq.g1vaaAzhUyIpsoaMhSDhxDsX8IuG38K');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9fd1a98a-ffe2-428a-8c37-03658050012e', '322a1e1c-b550-4cdb-b3f2-b7d59f9f503a', 'Signals and Traps', 'Run the command sleep 100 in the background. Find its PID with jobs or pgrep. Send it a SIGTERM signal using kill. Verify the process is gone by running ps aux | grep sleep. What signal did you send to terminate the process?', 100, '$2b$10$Bfa.T0nvGlC4M8E9Fj.FQ.909W7ymtZHVCXAzhTId1k7VhiOCERFa');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('43316587-3480-448b-aaa4-67b47292361b', '322a1e1c-b550-4cdb-b3f2-b7d59f9f503a', 'Disk Usage Sorting', 'Run du -sh /etc/* to list sizes of items in /etc. Pipe to sort -hr to sort by human-readable size descending. Report the name and size of the largest item. What is the largest directory or file in /etc by disk usage?', 100, '$2b$10$lMaejcNg6qgPBRUnYIU3a.hjvUMURq1JH4iHSvoWL9EilB/LZNs.u');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a9808e3e-fe8d-4090-b207-04d466ce3c1b', 'def2c670-6ec3-4a82-8df9-e1b74237df6e', 'ACLs with setfacl', 'Create a file called acl-test.txt. Use setfacl -m u:root:rwx acl-test.txt to grant root full ACL access. Then run getfacl acl-test.txt to display the ACL entries. What is the ACL permission mask value shown?', 100, '$2b$10$HcfoVH22kbSnmX9r8bI23Of5zMsPPuup3MTNc9kV7kWHNGx4Lbh6O');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('577ce226-8973-47b3-b073-59dca08abfcd', 'def2c670-6ec3-4a82-8df9-e1b74237df6e', 'Find by Permission with -perm', 'Run find / -perm -u=s -type f 2>/dev/null to locate files with the SUID bit set. Count how many results are returned. Then pick one result and report its full path. What is the full path of one SUID file found?', 100, '$2b$10$y9pKd1MeuvJ0/vNUjkHoju3BLbhM5EfG7mEV49QNh/EnHrkPBnV8C');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('53d38b1c-76fb-40f6-8880-7f24d87d1a17', 'def2c670-6ec3-4a82-8df9-e1b74237df6e', 'Immutable Flag with chattr', 'Create a file called immutable-test.txt with some content. Run chattr +i immutable-test.txt to make it immutable. Attempt to write to it with echo append >> immutable-test.txt and observe the error. Then run lsattr immutable-test.txt. What attribute letter is displayed?', 100, '$2b$10$n/DrADN4Mt4B41I21hLm0eeM3W4xLkZKjyeSa23eNN.KJW9JbviQu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5fe7a52b-5339-40fd-a611-476102556b26', 'def2c670-6ec3-4a82-8df9-e1b74237df6e', 'Umask Configuration', 'Run umask to display the current umask value. Then set the umask to 0022 with umask 0022. Create a new file called umask-test.txt. Run ls -l umask-test.txt to check its permissions. What are the permissions of the newly created file?', 100, '$2b$10$qUY.kl9D4JCG4UDZb9fuDu2G5UwwXCDqTNtxstmDc6R6/gNru0Hr2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2261edd6-8237-4445-a966-854036551d05', 'def2c670-6ec3-4a82-8df9-e1b74237df6e', 'SGID Bit on Directories', 'Create a directory called sgid-test. Run chmod g+s sgid-test to set the SGID bit. Create a file inside it called sgid-file.txt. Run ls -l on the directory and the file. What group owns the newly created file?', 100, '$2b$10$2dWBnRUru6JQApcVwNHbJ.3ALVJzTCnOpFP6mfezD71NzT82d6Z6a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6bd7e5de-2c23-419b-8a8b-51781b532364', '989bd7ac-13fd-4e6f-b502-3ff3b334c350', 'Create and Enable a Systemd Service', 'Create a file at /etc/systemd/system/hello.service with the following content: [Unit] Description=Hello Service, [Service] ExecStart=/bin/echo hello, [Install] WantedBy=multi-user.target. Run systemctl daemon-reload then systemctl enable hello.service. Run systemctl status hello.service. What is the Active status line?', 100, '$2b$10$cKEUVKn.0p9GNvzzCc3O8u8Mdg.wVYDGtvrL.wU1AZklv7Ko1OQQW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5ed4d141-f1f6-474f-aa72-a5f4691cb183', '989bd7ac-13fd-4e6f-b502-3ff3b334c350', 'Query Logs with journalctl', 'Run journalctl -u ssh --no-pager -n 20 to view the last 20 lines of SSH logs. Count how many log entries mention the word Accepted. What is the total count of Accepted entries?', 100, '$2b$10$tnmVWPy7s5J9XWTFqxnczOHClLWdx2HKZU8fme/zm3MvPXJjWfTCa');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('585eae41-f9bd-4a09-bc5d-8c1b67380853', '989bd7ac-13fd-4e6f-b502-3ff3b334c350', 'Nice and Renice Priority', 'Run ps -eo pid,ni,comm | head to view nice values of running processes. Start a new process with nice -n 10 sleep 60 in the background. Find its PID. Then run renice -n -5 -p PID to lower its nice value. Run ps -eo pid,ni,comm | grep sleep to verify. What is the updated nice value?', 100, '$2b$10$48yEOe3AZx/NH//s75EMvugbiMl/lVglHPqvsaErIop0I7.a8JfdG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('22a06b3f-0d25-4bb5-8549-d42a10cd42e1', '989bd7ac-13fd-4e6f-b502-3ff3b334c350', 'Custom ps aux Formatting', 'Run ps -eo pid,ppid,user,%cpu,%mem,comm --sort=-%cpu to list processes sorted by CPU usage. Identify the top process. Report its PID, user, and CPU percentage. What is the PID of the highest CPU process?', 100, '$2b$10$wkhXsBaVnjdPXLOcPCocwOIFFLU22LbksiJyuVLhW6qEsrDgu.yIK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d03e7d77-50eb-42cf-95cf-997ca366b84a', '989bd7ac-13fd-4e6f-b502-3ff3b334c350', 'Nohup and Disown', 'Run nohup sleep 100 & to start a background process immune to hangups. Run disown to remove it from the job table. Verify it is still running with ps aux | grep sleep. What PID was assigned to the nohup process?', 100, '$2b$10$DoQuHh7gPct7qGu2aEGf6eIZbsJI/fCIoLsJRLdF7bXUgGNtn8KoG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b9639163-45ac-47e5-9406-10076f978812', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Awk Fields and NR', 'Run awk -F: NR==1 {print NR, $1, $3} /etc/passwd to extract the first line of passwd. Then run awk -F: NF==7 {count++} END {print count} /etc/passwd to count lines with 7 fields. How many lines in /etc/passwd have exactly 7 colon-separated fields?', 100, '$2b$10$5IPgWVIGjuaPPXpJwFBUD.c/ZmvdaEk3uLj5bo6uqO2m7q1F6EGdS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('29e3515b-ec46-42da-9d99-2bd459c76bdc', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Sed Substitution', 'Copy /etc/passwd to /tmp/sed-test.txt. Run sed -i "s/root/superuser/g" /tmp/sed-test.txt. Verify with grep superuser /tmp/sed-test.txt. How many lines were changed?', 100, '$2b$10$rcmrOviKF8UNWyiauENDW.Ciwbl9xDavzFlAxm1zp.472nHTUgBdC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ba471bb3-39e4-4e39-9959-1ece470f6caf', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Cut with Custom Delimiter', 'Run cut -d: -f1,3,6 /etc/passwd to extract username, UID, and home directory. Pipe to head -5 to see the first 5 results. What is the third field (home directory) of the second line?', 100, '$2b$10$oL7J1hHXWlWdL1VMqMPZ8e4QoJHNVUVvvTwj6/baLPJcoxZRiFYTq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1f2fe90a-0a72-42dc-8509-2f464caceea7', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Tr Character Translation', 'Run echo "Hello World 123" | tr "[:upper:]" "[:lower:]" to convert to lowercase. Then run echo "abracadabra" | tr -d "a" to delete all a characters. What is the result of the second command?', 100, '$2b$10$rWI2ldostQYbv8PXa0q7M.3m.6gr0FiSBEGufauPc2bXYp.lMw1U.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dfec8bb9-d556-44d6-8191-bdc7daf9c544', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Sort with Key and Numeric', 'Run ps -eo pid,%cpu --no-headers | sort -k2 -rn | head -5 to list the top 5 processes by CPU usage sorted numerically descending. What is the PID of the top process?', 100, '$2b$10$2mUUwNpBjvRUOo5GjyxnROWOWbTQhKBqxiKye7/c05uj52tbWjisa');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3684f08c-98b2-4d34-90a3-6ba8b9f069b8', 'e5b52cdf-1435-4b77-896a-41a270c88021', 'Xargs Execution', 'Run find /tmp -maxdepth 1 -type f 2>/dev/null | xargs ls -l to list all files in /tmp with full details. Count the total number of lines output. How many files were listed?', 100, '$2b$10$pl.72uSLKIHy6vaWrXqVh.5D1GzvyB2WgcI41.N8mIqmRg8JS5uEy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2b3c293e-9701-4170-8d5b-c6d3b94e5ec1', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Rsyslog Forwarding', 'Add the line *.* @@127.0.0.1:514 to /etc/rsyslog.d/forward.conf. Restart rsyslog with systemctl restart rsyslog. Send a test message with logger -p local0.info test-forward-message. Check if the message appears in /var/log/syslog. What facility and level did you use?', 100, '$2b$10$rwWEAK7Ae.cwWlrrrpJ/neuvX9k79S70PYU/YyYbZmclOinpdtCya');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('930c94eb-164e-4f23-96b9-b0434e1a4ab5', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Logger Command', 'Run logger -t myapp -p daemon.warning "disk space low" to send a warning to syslog. Then run grep myapp /var/log/syslog to find it. What tag was used in the log entry?', 100, '$2b$10$uQ.9WIRnO8p6nlbSRf3Ggu9qM4/qF7.o5HlWTLt45ZT.gtRqyowXi');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('21b38418-d95d-411f-a48c-d93f7e7d747b', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Logrotate Custom App', 'Create /etc/logrotate.d/myapp with contents: /var/log/myapp/*.log { daily rotate 7 compress delaycompress missingok notifempty }. Create the log directory with mkdir -p /var/log/myapp and touch a dummy log file. Run logrotate -d /etc/logrotate.d/myapp to test the configuration in debug mode. How many rotations are configured?', 100, '$2b$10$GLcjkj/KWQnV0Dz7m8FEI.iBQw12CQs7KvgoIj5W1Vs2VTeA77rPW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4035febd-cba5-42e1-884e-6d1b21d5ab95', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Tail Follow with PID', 'Start a process that writes to /tmp/tailtest.log every second using: while true; do echo tick >> /tmp/tailtest.log; sleep 1; done &. Note the PID. Then run tail -f --pid=PID -n 1 /tmp/tailtest.log to follow the file until that PID exits. What flag did you use to track the writing process?', 100, '$2b$10$GiwwzJm./vwLSm2NnNxB5OcgS/zx.QTqlqmeQR5dSYlipiE2OP3ya');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5e3aa136-dc85-4669-8934-01e61a656408', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Dmesg Filtering', 'Run dmesg | tail -20 to view the last 20 kernel messages. Then run dmesg | grep -ci memory to count how many lines mention memory. What is the case-insensitive count of memory-related kernel messages?', 100, '$2b$10$tFtOvu4kaB3ParWpcqawf.9A/doJxvwwf2M6acUnKenu4GrqaGzka');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cad2e10c-9cae-4818-bbcb-b9aea9491a0d', '4a07684f-30df-4ece-b9bc-57a2727769d4', 'Syslog Facility Levels', 'Create /etc/rsyslog.d/custom.conf with: :programname, isequal, "mytest" /var/log/mytest.log. Restart rsyslog. Run logger -t mytest -p local5.notice "level test message". Verify the message appears in /var/log/mytest.log. What facility and severity level did you use?', 100, '$2b$10$xC.q/KCvJHLehPSueEG7QuGgyoVcioTAzb7kQQukhZXALAYr15Dxy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('da05cb2c-330f-4fe0-881c-26eadefbf15e', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'JOIN Queries on Lab Data', 'Connect to MySQL with mysql -u root -p. Run SELECT l.title, COUNT(f.id) AS flag_count FROM "Lab" l JOIN "LabFlag" f ON l.id = f."labId" GROUP BY l.id, l.title ORDER BY flag_count DESC LIMIT 5; to count flags per lab. Which lab has the most flags?', 100, '$2b$10$XC9/0xAOtDqMjyGwPblXZOIoVNa7tL12Sioxd9pJQcxcxtsK5xjwy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b2d0652b-2b43-4000-b3f3-29cb4505480b', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Stored Procedure for Flag Search', 'Connect to MySQL. Create a stored procedure: CREATE PROCEDURE FindFlagsByPoints(IN min_pts INT) SELECT title, points FROM "LabFlag" WHERE points >= min_pts; Then call it with CALL FindFlagsByPoints(100); How many flags have 100 or more points?', 100, '$2b$10$Iu4tlBo9nET50L4IHNOX6.tSWgqcNlTAPk.5W8cou3P0zhhMm8zQ6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('12e47566-f11d-47f0-9280-0d38093e529e', '88de7b45-d1c8-4d13-97df-66805199f591', 'EXPLAIN ANALYZE Query Plan', 'Connect to PostgreSQL with psql. Run EXPLAIN ANALYZE SELECT l.title, f.title AS flag_title, f.points FROM "Lab" l JOIN "LabFlag" f ON l.id = f."labId" WHERE f.points = 100 ORDER BY l.title LIMIT 10; to analyze the query plan. What is the execution time shown in milliseconds?', 100, '$2b$10$pEkBBgNlSUfFNwobnErK7e6GZSc2IkT6QBsQkLVrVRkCxP6kQGKXG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7f859abc-9015-412d-8537-fb00044c558b', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Docker Exec with Environment Variables', 'Run docker ps to list containers. Pick a running container. Execute docker exec CONTAINER_ID env to list all environment variables. Find the PATH variable. What is the first directory listed in the PATH?', 100, '$2b$10$v3fFDs6acaypZ.V29gMDeOv1t9Y7sPV4.aAkzj3qtvY3ZWGb0NyQ.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('45ef2deb-f906-4c33-a028-24f09e0aed2c', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Docker Inspect Specific Data', 'Run docker ps to list containers. Pick a container and run docker inspect --format "{{.NetworkSettings.IPAddress}}" CONTAINER_ID to get its IP address. What is the IP address of the container?', 100, '$2b$10$OMU81nNuwG1Ka1Spd4MCxu6jB.5kp35FGwkXOJlOHtEm08oijSM.K');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ba947925-afaf-4767-9c85-b573a66d18da', '50d6a493-7898-473d-8287-137229593da9', 'WebSocket Proxy Pass', 'Create /etc/nginx/conf.d/ws.conf with: server { listen 8080; location /ws { proxy_pass http://127.0.0.1:3000; proxy_http_version 1.1; proxy_set_header Upgrade $http_upgrade; proxy_set_header Connection "upgrade"; } }. Run nginx -t to test. What header enables WebSocket support?', 100, '$2b$10$.HoScbuRSPMXImLw0SZgtufgFlLR5waEQac9n8O6LdcjTVJXYNG/m');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bd360a62-7a9e-405b-aab5-7d580c948ea1', '50d6a493-7898-473d-8287-137229593da9', 'Client Max Body Size', 'Create /etc/nginx/conf.d/upload.conf with: server { listen 8090; client_max_body_size 50m; location /upload { return 200 "ok"; } }. Run nginx -t to test the configuration. What is the maximum upload size configured?', 100, '$2b$10$b1Sz/F3GbSJAhq35KFA5GumFGNqnASlFYhfSoSKUSf9CrSU4mq7aG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0479d925-70f1-4957-9a35-76f0d134711f', '50d6a493-7898-473d-8287-137229593da9', 'Upstream Health Checks', 'Create /etc/nginx/conf.d/upstream.conf with: upstream backend { server 127.0.0.1:3001; server 127.0.0.1:3002 backup; } server { listen 8091; location / { proxy_pass http://backend; } }. Run nginx -t to verify. What keyword marks the failover server?', 100, '$2b$10$U3iqoTfVa7T4OFb0o1FcguBbInZB5N/CSbjP2UoSuanSoOFpt3W4.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c609ce83-3a94-495e-a827-36607ff0d4c7', '50d6a493-7898-473d-8287-137229593da9', 'Try Files for SPA', 'Create /etc/nginx/conf.d/spa.conf with: server { listen 8092; root /var/www/html; try_files $uri $uri/ /index.html; }. Run nginx -t to test. What fallback file is served when no route matches?', 100, '$2b$10$ftFx64N1VBwAAKy9A3aSSeznKPsANp0WLzPSX7fiEBSoFcuxJhzwC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('35fc2f86-d004-48ac-89dc-54133e8683e0', '50d6a493-7898-473d-8287-137229593da9', 'Basic Authentication', 'Create a password file with htpasswd -c /etc/nginx/.htpasswd admin. Create /etc/nginx/conf.d/auth.conf with: server { listen 8093; auth_basic "Restricted"; auth_basic_user_file /etc/nginx/.htpasswd; location / { return 200 "welcome"; } }. Run nginx -t to verify. What directive enables the login prompt?', 100, '$2b$10$QNqMoq2Mm6TvJKaA/4NXruoMAF62tGp/drC6oBg4YnPlggOyfTVn6');
